
local kk=[==[]==]
local mzg=
(function(...)
local lbvd={98,200,133,177,6,164,190,89,128,170,150,38,122,246,28,132,173,18,56,103}
local vc=bit32 or bit
local bv=vc.bxor
for vs=1,#lbvd do lbvd[vs]=bv(lbvd[vs],(95*vs+228)%256) end
local aopux="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local xvgx={}
for lcq=1,#aopux do xvgx[aopux:byte(lcq)]=lcq-1 end
local function vtn(str)
  local R={} local acc,nb=0,0
  for jrwhc=1,#str do
    local v=xvgx[str:byte(jrwhc)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function hqj(key,data)
  local S={} for ov=0,255 do S[ov]=ov end
  local j=0
  for ttsoi=0,255 do
    j=(j+S[ttsoi]+key[(ttsoi%#key)+1])%256
    S[ttsoi],S[j]=S[j],S[ttsoi]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(bv(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=hqj(lbvd,vtn(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local zxja=nf()
return function(big) return zxja(big) end
end)(...)

return mzg(kk)
